SELECT mp.subject_id AS male_patient_id, fp.subject_id AS female_patient_id, sp.subject_id AS stroke_patient_id, COUNT(DISTINCT i.subject_id) AS total_patients, SUM(CASE WHEN i.map < 65 THEN 1 ELSE 0 END) AS patients_with_low_map, SUM(CASE WHEN i.map BETWEEN 65 AND 74 THEN 1 ELSE 0 END) AS patients_with_medium_map, SUM(CASE WHEN i.map BETWEEN 75 AND 84 THEN 1 ELSE 0 END) AS patients_with_high_map, SUM(CASE WHEN i.map >= 85 THEN 1 ELSE 0 END) AS patients_with_very_high_map, SUM(CASE WHEN i.itemid = 657075 THEN 1 ELSE 0 END) AS patients_with_stroke FROM male_patients mp CROSS JOIN female_patients fp CROSS JOIN stroke_patients sp JOIN icustays i ON mp.subject_id = i.subject_id OR fp.subject_id = i.subject_id OR sp.subject_id = i.subject_id GROUP BY mp.subject_id, fp.subject_id, sp.subject_id;